    diag_blast_desc: 'கீழ் இலை பகுதியில் சாம்பல் நிற மையத்துடன் கூடிய கதிர் வடிவ புண்கள் காணப்படுகின்றன. பாதிக்கப்பட்ட பகுதி தற்போது மண்டலம் 2 இல் 18% ஆகும்.',
