    diag_irrig_advisory: 'மண் ஈரப்பதத்தை 32% இலிருந்து 55% ஆக உயர்த்த மண்டலம் 1 க்கு 45 நிமிட பாசனம் தேவை. குலைநோய் ஈரப்பதத்தை தடுக்க மண்டலம் 2 பம்ப் அணைக்கப்பட வேண்டும்.',
