    diag_water_saved: 'இந்த பருவத்தில் ஒட்டுமொத்த நீர் சேமிப்பு: 18.4% (~32,400 லிட்டர்).',
    diag_weather_spray: 'சுற்றுப்புற காற்று 11 கிமீ/மணி (பாதுகாப்பு வரம்பு 15 கிமீ/மணிக்குள்). 14 மணி நேரத்திற்கு மழை எதிர்பார்க்கப்படவில்லை. உகந்த தெளிப்பு நேரம்: இன்று மாலை 4:00 – 6:30.',
