    rep_rep_01_desc: 'பயிர் வளர்ச்சி வீரியம், மண் குறியீடுகள், முனை இணைப்பு மற்றும் செயல்பாட்டு திறன் ஆகியவற்றின் முழுமையான தொகுப்பு.',
