    rep_rep_02_title: 'தாவர விதான அடர்த்தி & பல-ஸ்பெக்ட்ரல் ஆரோக்கிய பகுப்பாய்வு',
    rep_rep_03_desc: 'குலைநோய் (Magnaporthe oryzae) மற்றும் பழுப்பு புள்ளி புண் கண்காணிப்பு, வரைபடங்கள் மற்றும் தீவிரத்தன்மை வரைபடங்கள்.',
