    rep_rep_03_period: 'நிகழ்நேர நிகழ்வு சாளரம்',
    rep_rep_03_title: 'நோய்க்கிருமி & வித்து பரவல் தணிக்கை',
    rep_rep_04_desc: 'இலை சுருட்டு புழு மடிப்பு எண்ணிக்கை, இனக்கவர்ச்சி பொறி குறியீடு மற்றும் இயற்கை எதிரிகள் சமநிலை.',
