    alt_alt_001_title: 'அதிக நோய் இடர் கண்டறியப்பட்டது (குலைநோய் 82%)',
    alt_alt_001_msg: 'மண்டலம் 2 இல் நோய் இடர் கண்டறியப்பட்டது. நுண் தட்பவெப்பநிலை நெல் குலைநோய் வித்து முளைப்பதற்கு மிகவும் சாதகமாக உள்ளது.',
    alt_alt_001_action: 'கதிர் வடிவ புண்களுக்காக கீழ் இலைகளை நேரில் ஆய்வு செய்யவும். புண்கள் 2% ஐ தாண்டினால் பரிந்துரைக்கப்பட்ட தெளிப்பை தயார் செய்யவும்.',
    alt_alt_002_title: 'குறைந்த மண் ஈரப்பதம் & நீர் அழுத்தம்',
    alt_alt_002_msg: 'மண்டலம் 1 இல் குறைந்த மண் ஈரப்பதம் (32%) கண்டறியப்பட்டது. தூர்கட்டும் நெல்லுக்கு நீர் பற்றாக்குறை ஏற்பட்டுள்ளது.',
    alt_alt_002_action: 'வேர் மண்டல ஈரப்பதத்தை 55% ஆக உயர்த்த மாலையில் 45 நிமிட பாசன சுழற்சியைத் தொடங்கவும்.',
    alt_alt_003_title: 'பூச்சி தாக்குதல் அச்சுறுத்தல்: இலை சுருட்டு புழு (78%)',
    alt_alt_003_msg: 'மண்டலம் 1 இல் சமீபத்திய படத்தில் அதிக இலை சுருட்டு புழு செயல்பாடு (78% உறுதிப்பாடு) கண்டறியப்பட்டது.',
    alt_alt_003_action: 'நீளமான இலை மடிப்புகளை சரிபார்க்கவும். தூருக்கு >1 சேதமடைந்த இலை இருந்தால் வேப்ப எண்ணெய் அல்லது இயற்கை பூச்சிக்கொல்லியைப் பயன்படுத்தவும்.',
    alt_alt_004_title: 'அதிக வெப்பம் & ஆவி அழுத்த பற்றாக்குறை இடர்',
    alt_alt_004_msg: 'மதிய விதான வெப்பநிலை 34°C ஐ எட்டும் என கணிக்கப்பட்டுள்ளது, இது மண்டலம் 1 இல் நீராவிப்போக்கு அழுத்தத்தை அதிகரிக்கும்.',
    alt_alt_004_action: 'வேர் மண்டலத்தை குளிர்விக்க மெல்லிய தேங்கிய நீர் அடுக்கை (2 செ.மீ) பராமரிக்கவும்.',
    alt_alt_005_title: 'திடீர் வெள்ள எச்சரிக்கை - அதிக நீர்வரத்து வரம்பு',
    alt_alt_005_msg: 'மண்டல வானிலை மையம் கனமழை எச்சரிக்கை விடுத்துள்ளது. தாழ்வான மண்டலம் 2 க்கு வெள்ள அபாயம் உள்ளது.',
    alt_alt_005_action: 'வடிகால் மதகுகளை உடனடியாக சுத்தம் செய்து அதிகப்படியான நீர் வழிகளைத் திறக்கவும்.',
    rec_rec_01_title: 'மண்டலம் 1: 45 நிமிட இலக்கு பாசனத்தை திட்டமிடுங்கள்',
    rec_rec_01_desc: 'தற்போதைய மண் ஈரப்பதம் 32% ஆகும், இது 45% வரம்பை விட மிகக் குறைவு. அடுத்த 18 மணி நேரத்திற்கு மழை இல்லை என கணிக்கப்பட்டுள்ளது.',
    rec_rec_02_title: 'மண்டலம் 2: கள ஆய்வு & குலைநோய் தடுப்பு மேலாண்மை',
    rec_rec_02_desc: 'CNN மாதிரி 82% குலைநோய் அபாயத்தை வெளிப்படுத்துகிறது. ஆரம்பகால பூஞ்சாணக்கொல்லி இலை குலைநோய் பரவுவதைத் தடுக்கிறது.',
    rec_rec_03_title: 'மண்டலம் 1: இலை சுருட்டு புழுவுக்கு விளக்கு/இனக்கவர்ச்சி பொறிகளை அமைக்கவும்',
    rec_rec_03_desc: 'அதிக அந்துப்பூச்சி செயல்பாடு கண்டறியப்பட்டது. ஏக்கருக்கு 4 பொறிகளை வைப்பது முட்டையிடும் நேரத்தை துல்லியமாக கண்டறிய உதவும்.',
